-- Editorial copy for each music box. Preserve products with administrator edits.
ALTER TABLE products ADD COLUMN editorial_json TEXT CHECK (editorial_json IS NULL OR json_valid(editorial_json));
UPDATE products SET editorial_json='{"story":"Capacul se deschide spre un mic univers de magie, iar mecanismul rămâne la vedere. O așezi printre cărțile preferate și fiecare rotire a manivelei readuce povestea mai aproape.","melody":"Modelul este asociat cu „Hedwig''s Theme”, tema pe care fanii o recunosc din primele note. Melodia dă unui obiect mic atmosfera unei întoarceri la Hogwarts.","use":"Deschide cutiuța la o pauză de lectură sau când vrei să-i arăți unui prieten un detaliu din colecția ta. Rotește manivela lent, în ritmul în care vrei să asculți.","gift":"Pentru un fan Harry Potter, la aniversare, Crăciun ori Secret Santa; o poți oferi alături de o carte sau de un mesaj personal.","closing":"O mică întoarcere la magie."}',name='Cutiuță muzicală Harry Potter „I''m a Keeper”',tagline='Pentru cineva care ține mereu puțină magie aproape.',short_description='Cutiuță din lemn închis, cu temă Harry Potter și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='hp-keeper' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET dimensions_text='aprox. 6,5 × 5 × 4 cm; cu capacul deschis, înălțime aprox. 6,2 cm' WHERE slug='hp-keeper' AND (dimensions_text IS NULL OR trim(dimensions_text)='');
UPDATE products SET editorial_json='{"story":"Lupul și mesajul „Winter Is Coming” fac din capac un semn ușor de recunoscut. Lemnul negru și mecanismul vizibil îi dau loc firesc lângă poveștile epice din bibliotecă.","melody":"Modelul este asociat cu tema principală Game of Thrones. Când rotești manivela, melodia aduce pentru câteva clipe atmosfera serialului în încăpere.","use":"Așaz-o pe birou sau lângă volumele fantasy și deschide capacul când vrei să împărtășești pasiunea pentru acest univers. Manivela controlează ritmul momentului muzical.","gift":"Pentru un fan Game of Thrones, la aniversare, Crăciun sau într-un schimb de cadouri între prieteni pasionați de fantasy.","closing":"Nordul încape într-un gest."}',name='Cutiuță muzicală Game of Thrones „Winter Is Coming”',tagline='Un semn din Nord pentru cineva care iubește legendele.',short_description='Cutiuță neagră din lemn, cu lup, mesaj tematic și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='got-winter' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET dimensions_text='aprox. 6,5 × 4 × 5 cm' WHERE slug='got-winter' AND (dimensions_text IS NULL OR trim(dimensions_text)='');
UPDATE products SET editorial_json='{"story":"Sub luna desenată, pisicuța transformă cutiuța într-un mic obiect de păstrat aproape. Lemnul deschis și detaliile gravate îi dau un aer cald, potrivit unui colț personal.","melody":"Modelul este asociat cu „La Vie en Rose”. Melodia completează firesc imaginea delicată, ca un mesaj tandru spus fără multe cuvinte.","use":"O poți lăsa pe noptieră sau pe birou și o poți porni într-o clipă liniștită, prin rotirea manivelei. Este un mod simplu de a-i spune cuiva „m-am gândit la tine”.","gift":"Pentru un iubitor de pisici, de ziua lui, la o aniversare în doi sau ca surpriză fără ocazie specială.","closing":"Un gest mic, cu multă tandrețe."}',name='Cutiuță muzicală Pisicuță și Lună',tagline='O surpriză blândă pentru omul care iubește pisicile.',short_description='Cutiuță din lemn deschis, cu pisicuță, lună și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='kitten' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET dimensions_text='aprox. 6,4 × 3,6 × 5 cm' WHERE slug='kitten' AND (dimensions_text IS NULL OR trim(dimensions_text)='');
UPDATE products SET editorial_json='{"story":"Ilustrația tematică aduce farmecul unei seri cu dovleci și povești spuse pe întuneric. Mecanismul la vedere face din cutiuță un mic detaliu de decor care merită descoperit de aproape.","melody":"Modelul este asociat cu „This Is Halloween”. Melodia accentuează atmosfera jucăușă și misterioasă a sezonului, fără să încarce decorul.","use":"Așaz-o lângă decorul de toamnă și pornește melodia când primești oaspeți sau pregătești o seară tematică. Se acționează manual, exact când vrei tu.","gift":"Pentru gazda unei petreceri de Halloween, un colecționar de obiecte tematice sau un prieten care așteaptă toamna tot anul.","closing":"Misterul începe cu o rotire."}',name='Cutiuță muzicală Halloween',tagline='Un strop de mister pentru serile de octombrie.',short_description='Cutiuță din lemn cu ilustrație de Halloween și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='halloween' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET dimensions_text='aprox. 6,4 × 3,8 × 5 cm' WHERE slug='halloween' AND (dimensions_text IS NULL OR trim(dimensions_text)='');
UPDATE products SET editorial_json='{"story":"Sub capac se află un mesaj care poate spune ce uneori e greu de rostit. Cutiuța păstrează acel gând într-un obiect mic, cald, pe care persoana dragă îl poate redeschide oricând.","melody":"Modelul este asociat cu „You Are My Sunshine”. Melodia face mesajul și mai personal, într-un moment scurt pe care îl pornești singur, prin manivelă.","use":"Ofer-o cu o dedicație și lasă persoana dragă să deschidă capacul și să pornească melodia. Poate rămâne apoi pe noptieră sau pe birou, la îndemână în zilele aglomerate.","gift":"Pentru partener, un părinte sau un prieten apropiat; potrivită la aniversare, de sărbători ori într-o zi obișnuită.","closing":"Spune-i cine îți aduce soarele."}',name='Cutiuță muzicală „You Are My Sunshine”',tagline='Pentru omul care îți luminează zilele.',short_description='Cutiuță din lemn închis, cu mesaj sub capac și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='sunshine' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET dimensions_text='aprox. 6,5 × 3,8 × 5 cm' WHERE slug='sunshine' AND (dimensions_text IS NULL OR trim(dimensions_text)='');
UPDATE products SET editorial_json='{"story":"Decorul Inelului face cutiuța să pară un mic obiect găsit într-o poveste veche. Pe un raft cu volume fantasy, devine un reper personal pentru cel care iubește Pământul de Mijloc.","melody":"Modelul este asociat cu „In Dreams”. Melodia adaugă un moment liniștit unei teme vizuale puternice, pentru cine recunoaște povestea dincolo de imagine.","use":"Așaz-o lângă cărți sau într-o colecție tematică și rotește manivela într-o pauză de lectură. Micul ritual lasă loc amintirii scenelor preferate.","gift":"Pentru un cititor Tolkien sau fan al filmelor, la aniversare, Crăciun ori Secret Santa; verifică disponibilitatea înainte de a planifica data cadoului.","closing":"Păstrează aproape povestea prețioasă."}',name='Cutiuță muzicală Stăpânul Inelelor „One Ring”',tagline='Pentru cel care se întoarce mereu în Pământul de Mijloc.',short_description='Cutiuță din lemn cu decor inspirat de Inel și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='lotr-rings' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET editorial_json='{"story":"Albastrul intens și mesajul de pe capac trimit la jocul de indicii al Hărții Hoinarului. Este un obiect mic care își găsește locul lângă cărțile și amintirile unui fan Harry Potter.","melody":"Modelul este asociat cu „Hedwig''s Theme”. Melodia leagă mesajul de pe capac de atmosfera cunoscută a poveștii, fără să fie nevoie de alte explicații.","use":"Deschide capacul, rotește manivela și lasă un prieten fan să ghicească de unde vine mesajul. Pe raft, cutiuța rămâne un semn discret al universului preferat.","gift":"Pentru un Potterhead, la aniversare, Crăciun sau un schimb de cadouri; verifică disponibilitatea înainte de a o promite pentru o dată fixă.","closing":"Un secret bun se dă mai departe."}',name='Cutiuță muzicală Harry Potter „I Solemnly Swear”',tagline='Un indiciu pentru cine știe drumul spre Hogwarts.',short_description='Cutiuță albastră din lemn, cu mesaj tematic și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='hp-always' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET editorial_json='{"story":"Capacul ilustrat aduce un strop de pădure fermecată într-un obiect de ținut aproape. Lemnul și imaginea luminoasă îi dau farmecul unei povești pe care o redeschizi din când în când.","melody":"Modelul este asociat cu „A Thousand Years”. Melodia completează tema cu o notă tandră, potrivită pentru un dar oferit cu gând bun.","use":"Așaz-o într-un colț de lectură sau pe o etajeră, apoi rotește manivela într-un moment de liniște. Poate însoți un mesaj scris de mână pentru cineva drag.","gift":"Pentru cine iubește poveștile fantasy, la aniversare, Crăciun sau ca gest de apreciere; verifică disponibilitatea înainte de alegerea datei.","closing":"Lasă puțină magie să rămână."}',name='Cutiuță muzicală Zâna Pădurii',tagline='O poveste delicată pentru cine iubește să viseze.',short_description='Cutiuță din lemn cu ilustrație de zână și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='fairy' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET editorial_json='{"story":"Corabia prinsă în furtună dă capacului energie și mișcare. Cutiuța aduce un mic episod de aventură pe biroul sau raftul celui atras de poveștile mării.","melody":"Modelul este asociat cu „He''s a Pirate”. Melodia ține pasul cu tema aventuroasă și face din rotirea manivelei începutul unei noi escapade.","use":"Deschide cutiuța înaintea unei seri de film sau arat-o unui prieten pasionat de povești maritime. Manivela pornește momentul muzical fără pregătiri speciale.","gift":"Pentru un fan al Piraților Caraibilor sau al aventurilor pe mare, la aniversare ori de sărbători; verifică disponibilitatea modelului.","closing":"Aventura începe în palmă."}',name='Cutiuță muzicală Pirații Caraibilor „Furtuna”',tagline='Pentru cel care ar alege oricând o nouă aventură.',short_description='Cutiuță din lemn cu ilustrație marină și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='pirates' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
UPDATE products SET editorial_json='{"story":"Mesajul de pe capac transformă un obiect tematic într-un gest foarte personal. Lemnul închis îi dă un aer matur, iar surpriza se descoperă când cutiuța este deschisă.","melody":"Modelul este asociat cu „Imperial March”. Melodia aduce o notă recognoscibilă și jucăușă pentru un tată care iubește Star Wars.","use":"Ofer-o împreună cu un mesaj de la tine și lasă-l pe tata să pornească muzica prin manivelă. O poate păstra apoi la birou, ca amintire a momentului.","gift":"Pentru ziua tatălui, aniversarea lui, Crăciun sau un simplu „mulțumesc”; verifică disponibilitatea înainte de ocazia aleasă.","closing":"Tata are propria lui galaxie."}',name='Cutiuță muzicală Star Wars „Best Dad in the Galaxy”',tagline='Pentru tata, eroul preferat din galaxia ta.',short_description='Cutiuță din lemn închis, cu mesaj pentru tata și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='starwars-dad' AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_type='product' AND a.entity_id=products.id AND a.action='product.update');
